use crate::pull;
use crate::tally;
use std::fs;
use std::path::Path;

pub fn rib_c() -> i32 {
    let _ = tally::lines();
    let dest = Path::new("/app/blotbay/rows.json");
    let _ = fs::remove_file(dest);

    let buf = match fs::read("/app/quaybag/night.bin") {
        Ok(buf) => buf,
        Err(err) => {
            eprintln!("weltquay: cannot read input: {}", err);
            return 1;
        }
    };
    let available_bits = buf.len().checked_mul(8).unwrap_or(usize::MAX);
    if available_bits < pull::WIDTH_BITS as usize {
        eprintln!(
            "weltquay: input has {} bits, layout requires {}",
            available_bits,
            pull::WIDTH_BITS
        );
        return 1;
    }

    let (a, b, c, d, e, f) = pull::dump(&buf);
    let body = format!(
        "{{\"kind\":{},\"lane\":{},\"mode\":{},\"welt\":{},\"tail\":{},\"mark\":{}}}\n",
        a, b, c, d, e, f
    );
    if let Some(parent) = dest.parent() {
        if let Err(err) = fs::create_dir_all(parent) {
            eprintln!("weltquay: cannot create output directory: {}", err);
            return 1;
        }
    }
    match fs::write(dest, body) {
        Ok(()) => 0,
        Err(err) => {
            eprintln!("weltquay: cannot write output: {}", err);
            let _ = fs::remove_file(dest);
            1
        }
    }
}
EOF
